import logo from './logo.svg';
import React,{useState,useEffect} from 'react';
import './App.css';

function App() {
  const [userName,setUserName]=useState("");
  const [pwd,setPwd]=useState("");
  const [value,setValue]=useState("");

  useEffect(()=>{
    if(userName!==""&&pwd!=="" && userName==="admin" && pwd==="admin123"){
      setValue(true);
    }
    else{
      setValue(false);
    }    
  },[userName,pwd]);//Use Effect Dependency

  const update=()=>{
    if(value){
      alert("Login Success");
    }
    else{
      alert("Login Failed");
    }
  }
  return (
    <div className='container'>
      <form onSubmit={update}>
        <label className="label1">UserName</label>
        <input type="text" className="input1" onChange={(e)=>(setUserName(e.target.value))}/>
        <label className="label2">Password</label>
        <input type="text" className="input2" onChange={(e)=>(setPwd(e.target.value))}/>
        <input type="submit"/>
      </form>
    </div>
  );
}

export default App;
